+	for k, v := range src {
+		srcMap, ok := v.(map[string]any)
+		if !ok {
+			dst[k] = v
+			continue
+		}
+
+		if existing, ok := dst[k].(map[string]any); ok {
+			mergeSettings(existing, srcMap)
+			continue
+		}
+
+		dst[k] = cloneSettingsMap(srcMap)
+	}
+}
