+func cloneSettingsMap(src map[string]any) map[string]any {
+	dst := make(map[string]any, len(src))
+	for k, v := range src {
+		if child, ok := v.(map[string]any); ok {
+			dst[k] = cloneSettingsMap(child)
+			continue
+		}
+		dst[k] = v
+	}
